contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run will attempt to claim rewards for a range of rounds and assert the relationship
    // between getUnclaimedRewards, numRoundsClaimed, and the number of mints (as detected
    // via FighterFarm.doesTokenExist through the public mintFromMergingPool observable effect).
    // Parameters:
    // - startRoundAdvance: number of rounds the caller already claimed (numRoundsClaimed[msg.sender] initial value)
    // - modelURIsLen: how many modelURIs/modelTypes/customAttributes entries we supply (must be >= possible wins)
    // - maxRoundsToAdvance: how many rounds currently exist (we cannot know roundId; but we rely on getUnclaimedRewards)
    function run(uint32 startRoundAdvance, uint16 modelURIsLen, uint32 maxRoundsToAdvance) public payable {
        // we will act as the InvMutTest contract (msg.sender for c calls)
        // Precondition: provide at least one candidate slot for model data
        require(modelURIsLen > 0);

        // Read initial unclaimed rewards for this contract's address
        uint256 beforeUnclaimed = c.getUnclaimedRewards(address(this));
        // Read initial numRoundsClaimed
        uint32 beforeNum = c.numRoundsClaimed(address(this));

        // We cannot directly set numRoundsClaimed (owner-only), but ensure our assumption by calling claimRewards
        // Prepare model arrays of given length (fill with empty strings and zeros)
        string[] memory modelURIs = new string[](modelURIsLen);
        string[] memory modelTypes = new string[](modelURIsLen);
        uint256[2][] memory customAttributes = new uint256[2][](modelURIsLen);
        for (uint16 i = 0; i < modelURIsLen; i++) {
            modelURIs[i] = "";
            modelTypes[i] = "";
            customAttributes[i][0] = 0;
            customAttributes[i][1] = 0;
        }

        // Try calling claimRewards and capture whether it reverts
        bool reverted;
        try c.claimRewards(modelURIs, modelTypes, customAttributes) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the call, read new values
        uint256 afterUnclaimed = c.getUnclaimedRewards(address(this));
        uint32 afterNum = c.numRoundsClaimed(address(this));

        // General rule asserted:
        // - numRoundsClaimed never decreases
        // - If call did not revert then numRoundsClaimed increased by some non-negative amount and
        //   the number of claimed rewards (beforeUnclaimed - afterUnclaimed) is <= number of modelURIs supplied
        // - If call reverted then state should be unchanged w.r.t. numRoundsClaimed and unclaimed rewards
        // We express this as a single assert combining these facts.
        assert(
            // monotonicity of numRoundsClaimed
            afterNum >= beforeNum
            && (
                // if reverted: both values unchanged
                (reverted && afterNum == beforeNum && afterUnclaimed == beforeUnclaimed)
                ||
                // if not reverted: unclaimed decreased by at most modelURIsLen and numRoundsClaimed advanced by at least 0
                (!reverted && beforeUnclaimed >= afterUnclaimed && beforeUnclaimed - afterUnclaimed <= modelURIsLen)
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Run attempts to call claimRewards with prepared arrays. It observes whether the call reverts,
    // then asserts a general invariant about numRoundsClaimed and unclaimed rewards described above.
    function run(uint16 modelEntries) public payable {
        require(modelEntries > 0);

        // Read initial observable state for this contract address
        uint32 beforeNum = c.numRoundsClaimed(address(this));
        uint256 beforeUnclaimed = c.getUnclaimedRewards(address(this));

        // Prepare arrays to pass to claimRewards
        string[] memory modelURIs = new string[](modelEntries);
        string[] memory modelTypes = new string[](modelEntries);
        uint256[2][] memory customAttributes = new uint256[2][](modelEntries);
        for (uint16 i = 0; i < modelEntries; i++) {
            modelURIs[i] = "";
            modelTypes[i] = "";
            customAttributes[i][0] = 0;
            customAttributes[i][1] = 0;
        }

        bool reverted;
        try c.claimRewards(modelURIs, modelTypes, customAttributes) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-call observable state
        uint32 afterNum = c.numRoundsClaimed(address(this));
        uint256 afterUnclaimed = c.getUnclaimedRewards(address(this));

        // Assert the general rule:
        // - numRoundsClaimed is non-decreasing
        // - if reverted: both numRoundsClaimed and unclaimed rewards unchanged
        // - if not reverted: unclaimed rewards did not increase, and any decrease is at most modelEntries
        assert(
            afterNum >= beforeNum
            && (
                (reverted && afterNum == beforeNum && afterUnclaimed == beforeUnclaimed)
                || (!reverted && afterUnclaimed <= beforeUnclaimed && (beforeUnclaimed - afterUnclaimed) <= modelEntries)
            )
        );
    }

    receive() external payable {}
}

