contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry exercising pickWinner and checking invariants
    function run(uint256[] calldata winners) public payable {
        require(winners.length > 0);
        // read current mutable observables
        uint256 oldRound = c.roundId();
        uint256 oldTotalPoints = c.totalPoints();
        uint256 winnersPer = c.winnersPerPeriod();
        // require the input length equals winnersPer to call pickWinner successfully
        require(winners.length == winnersPer);

        // read fighterPoints for each provided id before call
        uint256 len = winners.length;
        uint256[] memory beforePoints = new uint256[](len);
        uint256 sumBefore = 0;
        for (uint256 i = 0; i < len; i++) {
            beforePoints[i] = c.fighterPoints(winners[i]);
            sumBefore += beforePoints[i];
        }

        bool reverted;
        // perform the state-changing call; must be top-level
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After call: if it reverted then nothing guaranteed; if it didn't revert, check general rule
        if (!reverted) {
            // selection for oldRound should be complete
            bool sel = c.isSelectionComplete(oldRound);
            // winnerAddresses[oldRound] length must equal winnersPer and owners should be accessible
            address[] memory addrs = c.winnerAddresses(oldRound);
            uint256 addrLen = addrs.length;
            // sum of fighterPoints for those token ids must now be zero and totalPoints reduced by sumBefore
            uint256 sumAfter = 0;
            for (uint256 i = 0; i < len; i++) {
                sumAfter += c.fighterPoints(winners[i]);
            }
            uint256 newTotal = c.totalPoints();

            // assert the general invariant described in property_summary
            assert(
                sel &&
                addrLen == winnersPer &&
                sumAfter == 0 &&
                oldTotalPoints == newTotal + sumBefore
            );
        } else {
            // If reverted we still must reach the assert; express a general relation that holds on revert: roundId unchanged
            // This is a weaker guarantee but necessary to satisfy the single-assert rule reachability
            uint256 newRound = c.roundId();
            assert(newRound == oldRound);
        }
    }

    receive() external payable {}
}

