contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // pickWinner should only be callable by an admin; but msg.sender will be this contract.
    // We rely on the deployed C having the test contract as admin (checker deploys c and may set owner accordingly),
    // otherwise pickWinner will revert — we capture that.
    function run(uint256[] calldata winners, uint256 maxIdToProbe) public payable {
        require(winners.length > 0);
        // read totalPoints before
        uint256 beforeTotal = c.totalPoints();
        // compute sum of fighterPoints for listed winners by calling public getter per index
        uint256 sumBefore = 0;
        for (uint256 i = 0; i < winners.length; i++) {
            // only probe ids less than maxIdToProbe to avoid out-of-bounds in hypothetical internal loops; however
            // fighterPoints mapping is accessible for any uint so it's fine. We nevertheless accept the param.
            uint256 id = winners[i];
            uint256 pts = c.fighterPoints(id);
            sumBefore += pts;
        }

        // attempt pickWinner and capture revert
        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After call, read totalPoints and fighterPoints for winners
        uint256 afterTotal = c.totalPoints();
        uint256 sumAfter = 0;
        for (uint256 i = 0; i < winners.length; i++) {
            uint256 id = winners[i];
            uint256 pts = c.fighterPoints(id);
            sumAfter += pts;
        }

        // General rule: if pickWinner did not revert then totalPoints must have decreased by exactly sumBefore - sumAfter,
        // and each chosen winner's fighterPoints must be zero afterwards.
        // We express that: if reverted then we make no claim (assert still must be general), so assert implies !reverted => properties.
        assert(reverted || (beforeTotal >= afterTotal && beforeTotal - afterTotal == sumBefore - sumAfter && sumAfter == 0));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The test tries to call pickWinner and, if it succeeds, checks the observable invariants described above.
    // We take the winners array and read owners before the call to ensure the recorded winners match.
    function run(uint256[] calldata winners) public payable {
        require(winners.length > 0);

        // Snapshot current round and totalPoints before (we will observe roundId increment)
        uint256 beforeRound = c.roundId();

        // Read owners for each winner id before the call using the FighterFarm public ownerOf via c._fighterFarmInstance is not accessible.
        // But C exposes winnerAddresses per round AFTER pickWinner; however we can read owner via the fighter farm through C's fighter farm public instance? No.
        // The contract C has a private _fighterFarmInstance, but FighterFarm.ownerOf is accessible only via that instance; we cannot directly call it through c.
        // Instead, we can only observe that after successful pickWinner, winnerAddresses[beforeRound] should equal the owners at time of call
        // We therefore capture fighterPoints for winners before the call to ensure they are zeroed.

        // Read fighterPoints before
        uint256 sumBefore = 0;
        for (uint256 i = 0; i < winners.length; i++) {
            sumBefore += c.fighterPoints(winners[i]);
        }

        // Attempt to call pickWinner and capture whether it reverts
        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read values after
        uint256 afterRound = c.roundId();
        bool selectionComplete = c.isSelectionComplete(beforeRound);

        // Sum fighterPoints after for the same ids
        uint256 sumAfter = 0;
        for (uint256 i = 0; i < winners.length; i++) {
            sumAfter += c.fighterPoints(winners[i]);
        }

        // winnerAddresses[beforeRound] is readable; ensure its length equals winners.length when the call succeeded
        address[] memory recorded = c.winnerAddresses(beforeRound);

        // General rule asserted: if pickWinner succeeded then
        // - roundId increased by 1
        // - isSelectionComplete[beforeRound] is true
        // - all chosen winners' fighterPoints were zeroed (sumAfter == 0)
        // - winnerAddresses[beforeRound] has same length as winners
        assert(reverted || (
            afterRound == beforeRound + 1 &&
            selectionComplete &&
            sumAfter == 0 &&
            recorded.length == winners.length
        ));
    }

    receive() external payable {}
}

