contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call pickWinner with an array of winner ids; if it succeeds, check observable invariants.
    function run(uint256[] calldata winners) public payable {
        // pickWinner requires winners.length == winnersPerPeriod and caller be admin. We cannot set admin here,
        // but the checker will run against deployed c where this contract is the deployer; still require non-empty.
        require(winners.length > 0);

        uint256 beforeRound = c.roundId();
        uint256 winnersPerPeriod = c.winnersPerPeriod();

        // To avoid out-of-bounds when reading fighterPoints, just sample the provided ids.
        // Snapshot sum of fighterPoints for provided ids.
        uint256 sumBefore = 0;
        for (uint256 i = 0; i < winners.length; i++) {
            sumBefore += c.fighterPoints(winners[i]);
        }

        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterRound = c.roundId();

        // If the call did not revert then we expect the contract to have advanced one round,
        // marked the previous round as complete, zeroed the fighterPoints for each winner id,
        // and stored winnerAddresses[beforeRound] with length equal to winnersPerPeriod.
        if (!reverted) {
            // read isSelectionComplete for the round we just completed (which is beforeRound)
