        // Simpler property: If getUnclaimedRewards(this)==0 then a call to claimRewards with empty arrays must not revert and must emit Claimed only if claimIndex>0; we can't observe events. But we can assert that after calling claimRewards, getUnclaimedRewards remains 0 and numRoundsClaimed doesn't decrease.

        // Read initial unclaimed
        uint256 beforeUnclaimed = c.getUnclaimedRewards(address(this));
        uint32 beforeRoundsClaimed = c.numRoundsClaimed(address(this));

        // Call claimRewards; it may revert due to nonReentrant if reentered, but here single call should succeed.
        bool reverted = false;
        try c.claimRewards(modelURIs, modelTypes, customAttributes) {
            reverted = false;
        } catch {
