    // We drive pickWinner then check getUnclaimedRewards and claimRewards behavior.
    // params: winners array (tokenIds) and arrays for claimRewards inputs sized to cover possible wins
    function run(uint256[] calldata winners, string[] calldata modelURIs, string[] calldata modelTypes, uint256[2][] calldata customAttributes) public payable {
        require(winners.length > 0 && winners.length <= 5); // keep bounded
        // must set winnersPerPeriod to winners.length so pickWinner will accept
        // updateWinnersPerPeriod is only callable by an admin; the test contract is the owner of freshly deployed C,
        // per harness, so it is an admin. Call to set winnersPerPeriod
        c.updateWinnersPerPeriod(winners.length);

        // Call pickWinner; this will record owners of the given tokenIds. It requires isAdmin[msg.sender], which holds.
        c.pickWinner(winners);

        // For the test, compute how many times this contract (address(this)) is among the winners of the previous round
        // We can only observe via getUnclaimedRewards, which should reflect wins from round 0..roundId-1.
        uint256 unclaimedBefore = c.getUnclaimedRewards(address(this));

        // Now try to claimRewards. If there are unclaimed rewards, claimRewards will call mintFromMergingPool on FighterFarm.
        // We cannot directly observe minted tokens here, but claimRewards will emit Claimed event when claimIndex>0.
        // call claimRewards with arrays at least as long as unclaimedBefore
        // Ensure provided arrays are long enough to satisfy potential claims
        require(modelURIs.length == modelTypes.length && modelURIs.length == customAttributes.length);
        // To avoid revert from out-of-bounds in claimRewards, require arrays length >= unclaimedBefore
        require(modelURIs.length >= unclaimedBefore);

        bool reverted;
        try c.claimRewards(modelURIs, modelTypes, customAttributes) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After claiming, getUnclaimedRewards must be zero for this claimer (all previously reported rewards are claimed)
        uint256 unclaimedAfter = c.getUnclaimedRewards(address(this));

        // The general property we assert:
        // 1) If the call to claimRewards did not revert, then unclaimedAfter == 0 and unclaimedBefore >= 0.
        // 2) If claimRewards reverted, we cannot assume state change, so require that it indeed reverted.
        // Combined into a single assert: either reverted is true OR unclaimedAfter == 0 AND unclaimedBefore >= unclaimedAfter.
        assert(reverted || (unclaimedAfter == 0 && unclaimedBefore >= unclaimedAfter));
    }

    receive() external payable {}
}

