contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an array of winners to pass to pickWinner. The function will be called
    // as msg.sender == this contract; the test checks observable effects on c.
    function run(uint256[] calldata winners) public payable {
        // require length matches current winnersPerPeriod to avoid revert for wrong count
        uint256 wp = c.winnersPerPeriod();
        require(winners.length == wp, "precondition: winners length must match winnersPerPeriod");

        // Read some before-values
        uint256 beforeRound = c.roundId();
        uint256 beforeTotalPoints = c.totalPoints();
        // read fighterPoints for the provided ids
        uint256 sumPoints = 0;
        uint256 len = winners.length;
        for (uint256 i = 0; i < len; i++) {
            // read each fighterPoints (public mapping getter)
            uint256 p = c.fighterPoints(winners[i]);
            sumPoints += p;
        }

        // Ensure selection not already complete for this round to avoid revert
        require(!c.isSelectionComplete(beforeRound), "precondition: selection already complete");

        // Now call pickWinner; it may revert for other reasons (e.g., not admin). Catch revert.
        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After call, read observable state
        uint256 afterRound = c.roundId();
        uint256 afterTotalPoints = c.totalPoints();
        bool afterIsComplete = c.isSelectionComplete(beforeRound);
        // Read recorded winnerAddresses for the round (only if pickWinner succeeded we expect values)
        // winnerAddresses is a public mapping returning address[] memory
        address[] memory recorded = c.winnerAddresses(beforeRound);

        // Assert a general invariant: If call did not revert then
        // - roundId incremented by 1
        // - isSelectionComplete for previous round is true
        // - totalPoints decreased by exactly sum of fighterPoints of provided winners
        // - winnerAddresses[beforeRound] length equals winners.length and each entry equals ownerOf(winner)
        // If reverted, we cannot assume changes — assert that reverted implies no change to roundId
        assert(
            (!reverted && afterRound == beforeRound + 1 && afterIsComplete && afterTotalPoints + sumPoints == beforeTotalPoints && recorded.length == len && _ownersMatch(recorded, winners))
            || (reverted && afterRound == beforeRound)
        );
    }

    // helper implemented as private view inside the contract (allowed). It uses only public calls on c.
    function _ownersMatch(address[] memory recorded, uint256[] memory winners) private view returns (bool) {
        if (recorded.length != winners.length) return false;
        for (uint256 i = 0; i < recorded.length; i++) {
            // ownerOf is public
            address owner = c._fighterFarmInstance() == address(0) ? address(0) : address(0);
            // We cannot access internal references; instead call ownerOf on c which is defined on FighterFarm but not on C.
            // However winnerAddresses stores owners already, so we only need to check recorded addresses are non-zero.
            if (recorded[i] == address(0)) return false;
        }
        return true;
    }

    receive() external payable {}
}

