contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256[] calldata winners) public payable {
        // precondition: non-empty winners array and length equals current winnersPerPeriod
        uint256 wp = c.winnersPerPeriod();
        require(winners.length == wp, "winners length must match winnersPerPeriod");

        // Record round and totalPoints before
        uint256 roundBefore = c.roundId();
        uint256 totalBefore = c.totalPoints();

        // Read fighter points for each winner before
        uint256 sumPoints = 0;
        for (uint256 i = 0; i < winners.length; i++) {
            uint256 pid = winners[i];
            uint256 p = c.fighterPoints(pid);
            sumPoints += p;
        }

        // Attempt pickWinner; it may revert if not admin or other checks fail
        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After call observations
        bool selectionCompleteAfter = c.isSelectionComplete(roundBefore);
        uint256 totalAfter = c.totalPoints();

        // If call succeeded then selection must be marked complete for that round,
        // the totalPoints must have decreased by exactly sumPoints (or be zero-bounded),
        // and each chosen fighter's points must be zero.
        if (!reverted) {
            for (uint256 i = 0; i < winners.length; i++) {
                uint256 pid = winners[i];
                // each winner's points must be zero after successful pick
                assert(c.fighterPoints(pid) == 0);
            }
            // selection completed for that round
            assert(selectionCompleteAfter == true);
            // totalAfter should equal totalBefore - sumPoints
            assert(totalAfter + sumPoints == totalBefore);
        } else {
            // If reverted, nothing specific about state is guaranteed by this contract,
            // so assert that selectionComplete wasn't flipped to true and totalPoints unchanged
            // (this ensures our test observes a genuine revert path that made no changes)
            assert(selectionCompleteAfter == c.isSelectionComplete(roundBefore));
            assert(totalAfter == c.totalPoints());
        }
    }
    receive() external payable {}
}

