contract InvMutTest {
    C c;
    address rankedBattle;
    constructor(C _c) { c = _c; rankedBattle = address(0x1234); }

    // single public test function
    function run(uint256 tokenId, uint256 points, address callerIs) public payable {
        // prepare: ensure points is nonzero to make meaningful change
        require(points > 0);

        // read before-values
        uint256 beforeTotal = c.totalPoints();
        uint256[] memory ptsArray = c.getFighterPoints(tokenId + 1);
        uint256 beforeFighterPoints = ptsArray.length > tokenId ? ptsArray[tokenId] : 0;

        // Try calling addPoints as msg.sender = this contract (which is NOT the rankedBattleAddress deployed in c)
        bool revertedUnauthorized = false;
        try c.addPoints(tokenId, points) {
            revertedUnauthorized = false;
        } catch {
            revertedUnauthorized = true;
        }

        // Now attempt to call addPoints by simulating the authorized caller by forwarding through a low-level call
        // We take an address parameter callerIs; the checker will supply some address. If callerIs equals the actual
        // _rankedBattleAddress in c, the low-level call will succeed; otherwise it should revert.
        bool revertedByCaller = false;
        bytes memory payload = abi.encodeWithSelector(c.addPoints.selector, tokenId, points);
        (bool ok,) = address(c).call(payload);
        // note: direct call above uses this contract as sender; to attempt sending from callerIs we cannot change msg.sender.
        // So instead we treat 'callerIs' parameter: if callerIs equals address(this) then our direct call above is from authorized sender
        // Read after-values
        uint256 afterTotal = c.totalPoints();
        uint256[] memory ptsArrayAfter = c.getFighterPoints(tokenId + 1);
        uint256 afterFighterPoints = ptsArrayAfter.length > tokenId ? ptsArrayAfter[tokenId] : 0;

        // General rule: if our addPoints call (the direct one) did not revert then both totals increased by points;
        // if it reverted then nothing changed. Also ensure unauthorized revert observed earlier is consistent.
        assert(
            (
                // call succeeded: diffs equal points
                ok && afterTotal == beforeTotal + points && afterFighterPoints == beforeFighterPoints + points
            ) || (
                // call failed: no change
                !ok && afterTotal == beforeTotal && afterFighterPoints == beforeFighterPoints
            )
        );
    }

    receive() external payable {}
}

